#include <dt-bindings/zmk/matrix_transform.h>

/ {
    chosen { zmk,kscan = &kscan0; zmk,matrix-transform = &default_transform; };
    default_transform: keymap_transform_0 {
        compatible = "zmk,matrix-transform";
        columns = <8>;
        rows = <5>;
        map = <RC(0,0) RC(0,1) RC(0,2) RC(0,3) RC(1,0) RC(1,1) RC(1,2) RC(1,3) RC(2,0) RC(2,1) RC(2,2) RC(2,3) RC(3,0) RC(3,1) RC(3,2) RC(3,3) RC(4,0) RC(4,1) RC(4,2) RC(0,4) RC(0,5) RC(0,6) RC(0,7) RC(1,4) RC(1,5) RC(1,6) RC(1,7) RC(2,4) RC(2,5) RC(2,6) RC(2,7) RC(3,4) RC(3,5) RC(3,6) RC(3,7) RC(4,4) RC(4,5) RC(4,6)>;
    };
    kscan0: kscan {
        compatible = "zmk,kscan-gpio-matrix";
        diode-direction = "col2row";
    };
};

#include <behaviors.dtsi>
#include <dt-bindings/zmk/keys.h>

/ {
    keymap {
        compatible = "zmk,keymap";
        base {
            bindings = <
                &kp Q  &kp W  &kp E  &kp R  &kp T  &kp Y  &kp U  &kp I  &kp O  &kp P  &kp A  &kp S  &kp D  &kp F  &kp G  &kp H  &kp LGUI  &kp SPACE  &kp LSHFT
                &kp J  &kp K  &kp L  &kp SEMI  &kp Z  &kp X  &kp C  &kp V  &kp B  &kp N  &kp M  &kp COMMA  &kp DOT  &kp FSLH  &kp N1  &kp N2  &kp RET  &kp BSPC  &kp LALT
            >;
        };
    };
};
